    keyword: kw,
    placement: checks.map((c) => ({ id: c.id, label: c.label, applies: c.applies, pass: c.pass })),
    occurrences: dens.occurrences,
    density: dens.density,
    terms,
    intent: {
      expected: (intent && intent.expected) || '',
      note: (intent && intent.note) || '',
